 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Support Contact Form</title>
     <meta
       name="description"
       content="A modern support contact form for reaching the product team."
     />
     <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
     <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
     <style>
       :root {
         color-scheme: light;
         --bg: #f5f7fb;
         --card: #ffffff;
         --text: #102033;
         --muted: #61708a;
         --border: #d9e1ec;
         --accent: #2563eb;
         --accent-hover: #1d4ed8;
         --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 40%),
           var(--bg);
         color: var(--text);
       }

       .page {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 32px 20px;
       }

       .card {
         width: 100%;
         max-width: 560px;
         background: var(--card);
         border: 1px solid rgba(217, 225, 236, 0.9);
         border-radius: 24px;
         box-shadow: var(--shadow);
         padding: 32px;
       }

       .eyebrow {
         margin: 0 0 8px;
         color: var(--accent);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0 0 12px;
         font-size: clamp(1.75rem, 3vw, 2.5rem);
         line-height: 1.1;
       }

       .lead {
         margin: 0 0 28px;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 18px;
       }

       .form-field {
         display: grid;
         gap: 8px;
       }

       label {
         font-size: 0.95rem;
         font-weight: 600;
       }

       input {
         width: 100%;
         border: 1px solid var(--border);
         border-radius: 14px;
         background: #fff;
         color: var(--text);
         padding: 14px 16px;
         font: inherit;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           transform 160ms ease;
       }

       input::placeholder {
         color: #9aa7b8;
       }

       input:focus {
         outline: none;
         border-color: rgba(37, 99, 235, 0.8);
         box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
       }

       .helper-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.875rem;
         line-height: 1.5;
       }

       .actions {
         margin-top: 6px;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 14px;
         background: linear-gradient(135deg, var(--accent), #4f46e5);
         color: #fff;
         font: inherit;
         font-weight: 700;
         padding: 14px 18px;
         min-width: 160px;
         cursor: pointer;
         box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
         transition:
           transform 160ms ease,
           box-shadow 160ms ease,
           background 160ms ease;
       }

       button:hover {
         background: linear-gradient(135deg, var(--accent-hover), #4338ca);
         transform: translateY(-1px);
         box-shadow: 0 16px 32px rgba(37, 99, 235, 0.28);
       }

       button:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.3);
         outline-offset: 3px;
       }

       @media (max-width: 640px) {
         .card {
           padding: 24px;
           border-radius: 20px;
         }

         button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const h = React.createElement;

       function Field({ id, label, type, placeholder, required, autoComplete, helperText }) {
         const helperId = helperText ? `${id}-help` : undefined;
         return h(
           "div",
           { className: "form-field" },
           h("label", { htmlFor: id }, label),
           h("input", {
             id,
             name: id,
             type,
             placeholder,
             required,
             autoComplete,
             "aria-describedby": helperId,
           }),
           helperText ? h("p", { className: "helper-text", id: helperId }, helperText) : null
         );
       }

       function SupportForm() {
         return h(
           "main",
           { className: "page" },
           h(
             "section",
             { className: "card", "aria-labelledby": "support-title" },
             h("p", { className: "eyebrow" }, "Support"),
             h("h1", { id: "support-title" }, "Contact our team"),
             h(
               "p",
               { className: "lead" },
               "Share your details and we’ll get back to you as soon as possible."
             ),
             h(
               "form",
               {},
               h(Field, {
                 id: "full-name",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jane Doe",
                 required: true,
                 autoComplete: "name",
               }),
               h(Field, {
                 id: "email-address",
                 label: "Email address",
                 type: "email",
                 placeholder: "jane@example.com",
                 required: true,
                 autoComplete: "email",
               }),
               h(Field, {
                 id: "phone-number",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "+1 555 123 4567",
                 required: false,
                 autoComplete: "tel",
                 helperText: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
               }),
               h(
                 "div",
                 { className: "actions" },
                 h("button", { type: "submit" }, "Send message")
               )
             )
           )
         );
       }

       ReactDOM.createRoot(document.getElementById("root")).render(h(SupportForm));
     </script>
   </body>
 </html>

